        "cardUrlRemoteEn": "https://karapfmpojnzolxlmsxv.supabase.co/storage/v1/object/public/yilore_cards/20/20-3a-en.webp",
        "cardUrlRemoteZh": "https://yilore-cards.oss-cn-hangzhou.aliyuncs.com/20/20-3a.webp"
