        "cardUrlRemoteEn": "https://karapfmpojnzolxlmsxv.supabase.co/storage/v1/object/public/yilore_cards/22/22-1a-en.webp",
        "cardUrlRemoteZh": "https://yilore-cards.oss-cn-hangzhou.aliyuncs.com/22/22-1a.webp"
